type Application struct {
	Server        *http.Server
	PromptAudit   *securityaudit.PromptService
	PluginManager *service.PluginManager
	Cluster       *cluster.Runtime
	Cleanup       func()
}

func provideClusterRuntime(cfg *config.Config, db *sql.DB, rdb *redis.Client, billing service.UsageBillingRepository, batch *service.BatchImageWorkerRuntime) (*cluster.Runtime, error) {
	r, err := cluster.NewRuntime(cfg, db, rdb)
	if err != nil {
		return nil, err
	}
	if recovery, ok := billing.(interface {
		RecoverClusterSettlements(context.Context) (int, error)
	}); ok {
		r.SetSettlementRecovery(recovery.RecoverClusterSettlements)
		if owner, ok := billing.(interface {
			ClusterRecoveryReserve() *cluster.RecoveryReserve
		}); ok {
			r.SetRecoveryReserve(owner.ClusterRecoveryReserve())
		}
	}
	if cfg.ClusterEnabled() {
		batch.SetNodeAdmission(func(ctx context.Context) (func(), error) {
			return r.Gate.Acquire(ctx, time.Duration(cfg.Cluster.QueueTimeoutMS)*time.Millisecond)
		})
		batch.Start()
	}
	return r, nil
}

func providePrivacyClientFactory() service.PrivacyClientFactory {
	return repository.CreatePrivacyReqClient
}

func provideServiceBuildInfo(buildInfo handler.BuildInfo) service.BuildInfo {
	return service.BuildInfo{
		Version:   buildInfo.Version,
		BuildType: buildInfo.BuildType,
	}
}

func providePluginHostInfo(buildInfo handler.BuildInfo) service.PluginHostInfo {
	return service.PluginHostInfo{
		Version:   buildInfo.Version,
		BuildType: buildInfo.BuildType,
	}
}

